INSERT INTO push_devices (user_id, platform, vendor, token, created_at, updated_at)
VALUES (#{userId}, #{platform}, #{vendor}, #{token}, #{now}, #{now})
ON DUPLICATE KEY UPDATE token = #{token}, updated_at = #{now}

mapper.delete:
DELETE FROM push_devices
WHERE user_id = #{userId}
  AND platform = #{platform}
  AND vendor = #{vendor}
